    if x < 0 and n > 0:
        return False
    if x < 0 and n < 0:
        # For negative x and negative n, we need odd exponents
        if x == -1:
            return True
        return False

    if x <= 0:
        return False

    # For positive numbers, check if we can find an integer exponent
    if n > 1:
        temp = 1
        while temp < x:
            temp *= n
        return temp == x
    elif n < 1:
