def minPath(grid, k):
    if not grid or not grid[0] or k <= 0:
        return []

    n = len(grid)
    if k == 1:
        # Find the minimum value in the entire grid
        min_val = float('inf')
        for i in range(n):
            for j in range(n):
                min_val = min(min_val, grid[i][j])
        return [min_val]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(row, col, path, remaining_steps):
        if remaining_steps == 0:
            return path[:]

        # Early termination: if current path is already lexicographically larger
        # than best found so far, we can skip this branch
        # But since we want the minimum, we'll explore all paths

        min_path = None
        current_value = grid[row][col]

        # Try all four directions
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc

            # Check bounds
            if 0 <= new_row < n and 0 <= new_col < n:
                path.append(grid[new_row][new_col])
                result = dfs(new_row, new_col, path, remaining_steps - 1)
                path.pop()

                if result is not None:
                    if min_path is None or result < min_path:
                        min_path = result

        return min_path

    # Try starting from each cell
    global_min_path = None

    for i in range(n):
        for j in range(n):
            # Start DFS from this cell
            path = [grid[i][j]]
            result = dfs(i, j, path, k - 1)

            if result is not None:
                if global_min_path is None or result < global_min_path:
                    global_min_path = result

    return global_min_path if global_min_path else []
